// Notación Big O: mide cómo crece el trabajo de un algoritmo a medida
    // que crece el tamaño de la entrada (n) — no el tiempo exacto en
    // milisegundos, sino la FORMA en la que ese tiempo escala.
    public class ComplejidadEjemplos
    {
        // O(1) — tiempo constante: no importa cuántos elementos tenga el
        // diccionario, buscar por clave siempre cuesta "lo mismo".
        public bool BuscarPorId(Dictionary<int, string> productos, int id)
        {
            return productos.ContainsKey(id);
        }

        // O(n) — tiempo lineal: en el peor caso, hay que recorrer todos
        // los elementos una vez. El costo crece proporcional a n.
        public bool BuscarPorIdLineal(List<(int Id, string Nombre)> productos, int id)
        {
            foreach (var producto in productos)
            {
                if (producto.Id == id) return true;
            }
            return false;
        }

        // O(n²) — tiempo cuadrático: un bucle anidado sobre la misma
        // colección. Con 10 elementos son 100 comparaciones; con 1.000
        // elementos son 1.000.000 — crece muy rápido y suele ser la
        // primera señal de que conviene otra estructura de datos.
        public List<(int, int)> EncontrarParesDuplicados(List<int> valores)
        {
            var duplicados = new List<(int, int)>();
            for (int i = 0; i < valores.Count; i++)
            {
                for (int j = i + 1; j < valores.Count; j++)
                {
                    if (valores[i] == valores[j]) duplicados.Add((i, j));
                }
            }
            return duplicados;
        }
    }

// Bottleneck (cuello de botella): el segmento de código que más tiempo
    // consume dentro de un loop crítico. No se adivina — se mide con un
    // profiler. Optimizar sin medir es la misma sobre-ingeniería que
    // agregar un patrón de diseño que nadie pidió: se paga complejidad
    // por un problema que quizás no existe.
    public class HotPathExample
    {
        // El "loop crítico" no es exclusivo de videojuegos: acá, el mismo
        // problema en el ciclo de vida de un request HTTP.
        public void ProcessRequest(HttpRequestData request)
        {
            ValidateInput(request);   // Procesamiento de "input"
            var result = RunBusinessLogic(request); // "Lógica" — el hot path más común
            SendResponse(result);     // Procesamiento de "output"
        }

        private void ValidateInput(HttpRequestData request) { }
        private object RunBusinessLogic(HttpRequestData request) => null;
        private void SendResponse(object result) { }
    }

    public class HttpRequestData { }

// Precomputation: evitar cálculo repetido en un hot spot, resolviéndolo
    // una sola vez de antemano y reutilizando el resultado. El mismo patrón
    // sirve para precalcular una tabla de conversión de moneda o de tasas
    // impositivas que no cambian durante la ejecución.
    public class PrecomputationExample
    {
        private const int TableSize = 360;
        private float[] _sinTable;
        private int _secondsPerDay;

        public void Initialize()
        {
            GenerateTables();
            _secondsPerDay = 60 * 60 * 24;
        }

        public void OnHotPath(int angleDegrees)
        {
            // Usa la tabla precalculada en vez de recalcular seno cada vez.
            float angleSin = _sinTable[angleDegrees % TableSize];
        }

        private void GenerateTables()
        {
            _sinTable = new float[TableSize];
            for (int i = 0; i < TableSize; i++)
            {
                _sinTable[i] = (float)Math.Sin(Math.PI / 180 * i);
            }
        }
    }

// Lazy computation: demorar un cálculo o una carga hasta el momento en
    // que realmente se necesita. Ejemplo universal: en una lista larga de
    // usuarios, no cargar la imagen de avatar de cada uno hasta que el
    // usuario haga scroll y ese ítem se vuelva visible en pantalla.
    public class LazyAvatarLoader
    {
        private readonly Dictionary<int, byte[]> _loadedAvatars = new();

        public byte[] GetAvatar(int userId, bool isVisibleOnScreen)
        {
            if (!isVisibleOnScreen)
            {
                return null; // No se carga nada si el ítem ni siquiera se ve.
            }
            if (!_loadedAvatars.ContainsKey(userId))
            {
                _loadedAvatars[userId] = DownloadAvatarFromServer(userId);
            }
            return _loadedAvatars[userId];
        }

        private byte[] DownloadAvatarFromServer(int userId) => Array.Empty<byte>();
    }

// Batching: agrupar operaciones similares y aplicarlas todas juntas, en
    // vez de una por una. Ejemplo universal: guardar 500 registros con un
    // solo INSERT por lotes en vez de 500 viajes individuales a la base de
    // datos — cada viaje tiene un costo fijo de red que el batching evita repetir.
    public class BatchRepository
    {
        // Mal: un viaje a la base de datos por cada registro.
        public void SaveOneByOne(List<Order> orders, IOrderRepository repository)
        {
            foreach (var order in orders)
            {
                repository.Save(order); // n viajes a la base de datos.
            }
        }

        // Bien: un solo viaje para todo el lote.
        public void SaveBatched(List<Order> orders, IOrderRepository repository)
        {
            repository.SaveBatch(orders); // 1 viaje a la base de datos.
        }
    }

    public class Order { }
    public interface IOrderRepository
    {
        void Save(Order order);
        void SaveBatch(List<Order> orders);
    }

// Caching: guardar temporalmente el resultado de una operación costosa
    // (una consulta a la base de datos, una llamada a una API externa) para
    // no repetirla si se vuelve a pedir lo mismo poco después.
    public class CachedExchangeRateService
    {
        private readonly Dictionary<string, (decimal Rate, DateTime FetchedAt)> _cache = new();
        private readonly TimeSpan _cacheDuration = TimeSpan.FromMinutes(10);

        public decimal GetRate(string currencyPair, IExchangeRateProvider provider)
        {
            if (_cache.TryGetValue(currencyPair, out var cached) &&
                DateTime.UtcNow - cached.FetchedAt < _cacheDuration)
            {
                return cached.Rate; // Hit de caché: no se llama a la API externa.
            }

            decimal freshRate = provider.FetchRate(currencyPair); // Miss: se paga el costo real.
            _cache[currencyPair] = (freshRate, DateTime.UtcNow);
            return freshRate;
        }
    }

    public interface IExchangeRateProvider
    {
        decimal FetchRate(string currencyPair);
    }

