// Optimización del Expected Path: se comprueba primero la condición
    // más probable, para que el caso común no pague el costo de evaluar
    // ramas menos frecuentes antes de llegar a la suya.
    public class RequestAuthExample
    {
        public void HandleRequest(bool isAuthenticated)
        {
            if (isAuthenticated)
            {
                // Caso común: la gran mayoría de los requests ya vienen autenticados.
                ProcessAuthenticatedRequest();
            }
            else
            {
                // Caso raro: solo entra acá el pequeño porcentaje sin sesión válida.
                RedirectToLogin();
            }
        }

        private void ProcessAuthenticatedRequest() { }
        private void RedirectToLogin() { }
    }

// Hashing: buscar por clave en un diccionario (hash table) es O(1);
    // buscar recorriendo una lista es O(n). Con pocos elementos no se nota
    // — con miles, es la diferencia entre una consulta instantánea y una lenta.
    public class ProductLookup
    {
        private readonly Dictionary<string, Product> _productsBySku = new();

        public void Index(Product product) => _productsBySku[product.Sku] = product;

        public Product FindBySku(string sku) =>
            _productsBySku.TryGetValue(sku, out var product) ? product : null; // O(1)
    }

    public class Product { public string Sku; }

    // Ejemplo de videojuegos: el mismo principio, aplicado a ubicar objetos
    // por posición en el mundo en vez de por clave — hashing espacial.
    public class GridHashing
    {
        public int GridCellSize = 10;
        private readonly Dictionary<(int, int), List<string>> _grid = new();

        public void Insert(string entityId, float worldX, float worldZ)
        {
            var cell = WorldToGridCell(worldX, worldZ);
            if (!_grid.ContainsKey(cell)) _grid[cell] = new List<string>();
            _grid[cell].Add(entityId);
        }

        private (int, int) WorldToGridCell(float x, float z) =>
            ((int)(x / GridCellSize), (int)(z / GridCellSize));
    }

// Object Pool — el concepto ancla de esta clase: pre-instancia los
    // objetos que van a hacer falta y los reutiliza (activar/desactivar) en
    // vez de crearlos y destruirlos en caliente. Ejemplo de videojuegos
    // (proyectiles), pero el mismo patrón sostiene, por ejemplo, los
    // connection pools de una base de datos: abrir una conexión es caro,
    // así que se abren varias de antemano y se reutilizan por request en
    // vez de abrir y cerrar una por cada consulta.
    public class ProjectilePool
    {
        private readonly Queue<Projectile> _pooled = new();
        private readonly Func<Projectile> _factory;

        public ProjectilePool(Func<Projectile> factory, int initialSize)
        {
            _factory = factory;
            for (int i = 0; i < initialSize; i++)
            {
                var projectile = _factory();
                projectile.IsActive = false;
                _pooled.Enqueue(projectile);
            }
        }

        public Projectile Get()
        {
            if (_pooled.Count > 0)
            {
                var projectile = _pooled.Dequeue();
                projectile.IsActive = true;
                return projectile;
            }
            // El pool se quedó corto: se crea uno de más como salvavidas,
            // aunque esto es exactamente el costo que el patrón busca
            // evitar — señal de que initialSize se quedó chico para el
            // pico real de demanda.
            var extra = _factory();
            extra.IsActive = true;
            return extra;
        }

        public void Return(Projectile projectile)
        {
            projectile.IsActive = false;
            _pooled.Enqueue(projectile);
        }
    }

    public class Projectile { public bool IsActive; }

// Heap vs Stack: un struct (tipo de valor) vive en el stack cuando es
    // una variable local — se apila y se libera automáticamente al salir
    // de scope. Una class (tipo de referencia) siempre vive en el heap,
    // aunque la referencia en sí (el "puntero" a esa posición) esté en el stack.
    public struct RequestResultValue // Tipo de valor: vive en el stack si es variable local.
    {
        public int StatusCode;
        public bool Success;
    }

    public class RequestResultReference // Tipo de referencia: el objeto en sí vive en el heap.
    {
        public int StatusCode;
        public bool Success;
    }

    public class HeapVsStackExample
    {
        public void HandleRequest()
        {
            // 'localValue' se guarda en el stack. Se libera automáticamente
            // al terminar HandleRequest() — sin intervención del Garbage Collector.
            RequestResultValue localValue = new RequestResultValue { StatusCode = 200, Success = true };

            // 'localReference' es una variable en el stack, pero apunta a un
            // objeto RequestResultReference que fue reservado en el heap.
            // Ese objeto en el heap solo se libera cuando el Garbage
            // Collector determina que ya nadie lo referencia.
            RequestResultReference localReference = new RequestResultReference { StatusCode = 200, Success = true };
        }
    }

// Memory Leak: el patrón más común en C# (no solo en videojuegos) es
    // suscribirse a un evento y nunca desuscribirse. Mientras el emisor del
    // evento siga vivo, va a mantener una referencia al suscriptor — y el
    // Garbage Collector nunca va a poder liberar al suscriptor, aunque el
    // objeto ya no se use en ningún otro lado.
    public class EventEmitter
    {
        public event Action OnSomethingHappened;

        public void Trigger() => OnSomethingHappened?.Invoke();
    }

    public class LeakySubscriber
    {
        private readonly EventEmitter _emitter;

        public LeakySubscriber(EventEmitter emitter)
        {
            _emitter = emitter;
            _emitter.OnSomethingHappened += HandleEvent;
        }

        // Fuga de memoria: no hay forma de desuscribirse — aunque el resto
        // del programa deje de usar este objeto, 'emitter' sigue teniendo
        // una referencia a HandleEvent, así que el GC nunca libera esto.

        private void HandleEvent() { /* ... */ }
    }

    public class FixedSubscriber : IDisposable
    {
        private readonly EventEmitter _emitter;

        public FixedSubscriber(EventEmitter emitter)
        {
            _emitter = emitter;
            _emitter.OnSomethingHappened += HandleEvent;
        }

        public void Dispose()
        {
            // Se desuscribe explícitamente: ahora el GC sí puede liberar
            // este objeto cuando corresponda.
            _emitter.OnSomethingHappened -= HandleEvent;
        }

        private void HandleEvent() { /* ... */ }
    }

// Stack Overflow: una llamada recursiva sin condición de salida llena
    // el espacio del stack y termina el programa con una excepción.
    public class StackOverflowExample
    {
        // Ejemplo de lo que NO hay que hacer: falta el caso base.
        int CalculateFactorialBroken(int n)
        {
            return n * CalculateFactorialBroken(n - 1); // Nunca llega a un caso base: stack overflow.
        }

        // Versión correcta: con condición de salida, cada llamada se apila
        // y se desapila normalmente sin agotar el stack.
        int CalculateFactorialFixed(int n)
        {
            if (n <= 1) return 1; // Caso base: corta la recursión.
            return n * CalculateFactorialFixed(n - 1);
        }
    }

// Memoria Estática: un campo static se comparte entre todas las
    // instancias de la clase y vive durante toda la ejecución del programa,
    // no por instancia individual.
    public class DiscountPolicy
    {
        // Compartido por todas las instancias: si una promoción global lo
        // cambia, afecta a todos los cálculos de precio que vengan después.
        public static float GlobalDiscountRate = 0f;
    }

    public class ShoppingCart
    {
        public decimal Subtotal;

        public decimal CalculateTotal()
        {
            // Todas las instancias de ShoppingCart leen el mismo valor estático.
            return Subtotal * (decimal)(1 - DiscountPolicy.GlobalDiscountRate);
        }
    }

// Garbage Collector: asignar memoria nueva dentro de un hot path (por
    // ejemplo, un 'new' innecesario en cada request o cada frame) genera
    // presión de GC constante. La versión "mala" ilustra el problema; la
    // "buena" reutiliza. Nota: el GC de .NET no funciona por conteo de
    // referencias — es generacional, por trazado (mark-and-sweep): agrupa
    // los objetos por "cuánto sobrevivieron" y revisa las generaciones
    // jóvenes con mucha más frecuencia que las viejas.
    public class GcPressureExample
    {
        // Mal: crea una lista nueva en el heap en cada llamada, aunque el
        // contenido termine siendo descartado — presión de GC innecesaria.
        public void ProcessRequestBad(List<int> incomingIds)
        {
            List<int> matchedIds = new List<int>();
            // ... se llena y se usa matchedIds acá ...
        }

        private readonly List<int> _reusableList = new List<int>();

        // Bien: la lista se reserva una sola vez y se reutiliza, solo se
        // limpia su contenido en cada llamada (Clear no libera la memoria reservada).
        public void ProcessRequestGood(List<int> incomingIds)
        {
            _reusableList.Clear();
            // ... se llena y se usa _reusableList acá ...
        }

        // GC.Collect() fuerza la recolección manualmente. Tiene un costo alto
        // en performance: se reserva para momentos muy puntuales (por ejemplo,
        // una pantalla de carga o un job de mantenimiento nocturno), nunca
        // dentro del hot path normal de la aplicación.
        public void ForceCollectionDuringMaintenanceWindow()
        {
            GC.Collect();
        }
    }

// Liberación de memoria en C#: a diferencia de C++ (delete explícito),
    // en C# no se libera memoria "a mano" — se quita la última referencia
    // al objeto, y el Garbage Collector se encarga de liberarlo cuando
    // determine que ya no es alcanzable.
    public class Session
    {
        public Session()
        {
            Console.WriteLine("Session created");
        }

        public void Close()
        {
            Console.WriteLine("Session closed");
        }
    }

    public class LiberacionDeMemoriaExample
    {
        public void Run()
        {
            Session session = new Session();
            session.Close();
            session = null; // Se quita la referencia: ahora el objeto es candidato para el GC.
        }
    }
